(window.NTDATA=window.NTDATA||{});(NTDATA.arar=NTDATA.arar||{}).rev={"1":{"1":"Հիսուս Քրիստոսի հայտնությունը, որ Աստված տվեց նրան՝ իր ծառաներին ցույց տալու, ինչ որ շուտով պիտի լինի, և իմացրեց իր հրեշտակի միջոցով՝ ուղարկելով իր Հովհաննես ծառային,","2":"որ վկայեց Աստծու խոսքը և Հիսուս Քրիստոսի վկայությունը, ինչ որ տեսավ։","3":"Երանի նրան, ով կարդում է այս մարգարեության խոսքերը և ով լսում ու պահում է այն, ինչ գրված է դրա մեջ, որովհետև ժամանակը մոտ է։","4":"Հովհաննեսից՝ Ասիայում գտնվող յոթ եկեղեցիներին։ Շնո՜րհ ձեզ և խաղաղություն նրանից, որ Է, նաև որ էր և որ գալու է, և այն յոթ Հոգիներից, որ նրա գահի առաջ են,","5":"և Հիսուս Քրիստոսից՝ հավատարիմ վկայից, որ անդրանիկն է մեռելներից և իշխանը երկրի թագավորների։","6":"և արքայության անդամներ և Աստծու ու իր Հոր քահանաներ դարձրեց մեզ. նրան փա՜ռք և զորություն հավիտյանս հավիտենից։ Ամեն։","7":"«Ահա նա գալիս է ամպերով, և նրան պիտի տեսնեն բոլոր աչքերը, նաև նրանք, որ խոցեցին նրան, և նրա վրա պիտի ողբան երկրի բոլոր ազգերը։ Այո՛, ամե՛ն»։","8":"«Ես եմ Ալֆան ու Օմեգան (սկիզբն ու վերջը)»,- ասում է Տերը՝ Աստված, նա, որ Է, որ էր և որ գալու է՝ Ամենակալը։","9":"Ես՝ Հովհաննեսս՝ ձեր եղբայրը, Հիսուսով ընկերակիցը նեղության, արքայության և համբերության, Աստծու խոսքի և Հիսուս Քրիստոսի վկայության համար եղա Պատմոս կոչված կղզում։","10":"Կիրակի օրը լցվեցի Հոգով և իմ հետևից փողի ձայնի պես մի բարձր ձայն լսեցի,","11":"որ ասում էր. «Ինչ որ տեսնում ես, գրի՛ր գրքում և ուղարկի՛ր Եփեսոսում, Զմյուռնիայում, Պերգամոնում, Թիատիրայում, Սարդիսում, Փիլադելփիայում և Լաոդիկիայում գտնվող յոթ եկեղեցիներին»։","12":"Ես շրջվեցի տեսնելու, թե ում ձայնն է ինձ հետ խոսում, և երբ շրջվեցի, յոթ ոսկե ճրագակալներ տեսա։","13":"Իսկ յոթ ճրագակալների մեջտեղում՝ մարդու Որդուն նման մեկին՝ երկարաքղանցք պատմուճան հագած, կրծքին ոսկե գոտի կապած։","14":"Նրա գլուխը և մազերը սպիտակ էին, ինչպես բուրդը, և ճերմակ, ինչպես ձյունը, և նրա աչքերը կրակի բոցի պես էին։","15":"Նրա ոտքերը նման էին հնոցի մեջ շիկացած պղնձի, իսկ նրա ձայնը՝ առատահոս ջրերի ձայնի։","16":"Իր աջ ձեռքում յոթ աստղեր ուներ. նրա բերանից սրած երկսայրի սուր էր ելնում, իսկ նրա երեսը ճառագում էր, ինչպես արեգակն իր զորությամբ։","17":"Երբ նրան տեսա, մեռածի պես նրա ոտքերի առաջ ընկա, իսկ նա իր աջն ինձ վրա դրեց ու ինձ ասաց. «Մի՛ վախեցիր, ես եմ Առաջինն ու Վերջինը","18":"և ողջը։ Ես մեռա և ահա կենդանի եմ հավիտյանս հավիտենից։ Ամեն։ Եվ ունեմ դժոխքի ու մահվան բանալիները։","19":"Գրի՛ր, ինչ որ տեսնում ես, ինչ որ կա, և ինչ որ նրանից հետո լինելու է։","20":"Ահավասիկ այն յոթ աստղերի և յոթ ոսկե ճրագակալների խորհուրդը, որ տեսար իմ աջ ձեռքին։ Յոթ աստղերը յոթ եկեղեցիների հրեշտակներն են, իսկ յոթ ճրագակալները՝ յոթ եկեղեցիները»։"},"2":{"1":"«Եփեսոսի եկեղեցու հրեշտակին գրի՛ր. \"Այսպես է ասում նա, ով յոթ աստղերն ունի իր աջ ձեռքում և շրջում է յոթ ոսկե ճրագակալների միջև.","2":"\"Գիտեմ քո գործերը, քո աշխատանքը, քո համբերությունը, և որ չարերին չես կարող տանել. փորձեցիր նրանց, ովքեր առաքյալ են ձևանում, բայց չեն, և սուտ համարեցիր նրանց։","3":"Համբերություն ունես։ Իմ անվան համար տանջվեցիր և չընկրկեցիր։","4":"Բայց քո դեմ բան ունեմ, որովհետև թողեցիր քո նախկին սերը։","5":"Արդ հիշի՛ր՝ որտեղի՛ց ընկար, զղջա՛ և նախկին գործերն արա՛, ապա թե ոչ, կգամ քեզ մոտ և քո ճրագակալն իր տեղից կշարժեմ, եթե չապաշխարես։","6":"Բայց սա ունես, որ ատում ես նիկոլայականների գործերը, որ ես էլ եմ ատում։","7":"Ով ականջ ունի, թող լսի, ինչ որ Հոգին ասում է եկեղեցիներին. \"Հաղթողին թույլ կտամ ուտել կենաց ծառից, որ Աստծու դրախտում է\"»։","8":"«Զմյուռնիայի եկեղեցու հրեշտակին գրի՛ր. \"Այսպես է ասում Առաջինն ու Վերջինը, որ մեռավ և կենդանացավ.","9":"\"Գիտեմ քո նեղությունը և աղքատությունը, բայց դու հարուստ ես։ Նաև հայհոյությունը նրանց, ովքեր իրենց կոչում են հրեա, բայց այլ բան չեն, քան սատանայի ժողովարան։","10":"Բնավ մի՛ վախեցիր այն բանի համար, որ պիտի չարչարվես։ Ահա բանսարկուն ձեզանից ոմանց բանտ է նետելու, որպեսզի փորձվեք, և տասն օր նեղություն եք ունենալու։ Հավատարի՛մ եղիր մինչև մահ, և կյանքի պսակը կտամ քեզ։","11":"Ով ականջ ունի, թող լսի, ինչ որ Հոգին ասում է եկեղեցիներին. \"Հաղթողը երկրորդ մահից չպիտի վնասվի\"»։","12":"«Պերգամոնի եկեղեցու հրեշտակին գրի՛ր. \"Այսպես է ասում նա, որ սրած երկսայրի սուր ունի.","13":"\"Գիտեմ, որ բնակվում ես այնտեղ, որտեղ սատանայի աթոռն է։ Սակայն պահում ես իմ անունը և չուրացար իմ հավատը այն օրերին, երբ իմ հավատարիմ վկա Անտիպասը սպանվեց ձեր մեջ, այնտեղ, որտեղ սատանան է բնակվում։","14":"Բայց քո դեմ մի փոքր բան ունեմ՝ այն, որ այդտեղ պահում ես Բաղաամի վարդապետությանը հետևողներին, որը Բաղակին սովորեցրեց Իսրայելի զավակներին գայթակղեցնել, որպեսզի նրանք կուռքերին զոհաբերված միս ուտեն և պոռնկություն անեն։","15":"Նույն կերպ էլ դու պահում ես նիկոլայականների վարդապետությանը հետևողներին։","16":"Ապաշխարի՛ր. եթե ոչ, շուտով կգամ քեզ մոտ ու կմարտնչեմ նրանց հետ իմ բերանի սրով։","17":"Ով ականջ ունի, թող լսի, ինչ որ Հոգին ասում է եկեղեցիներին. \"Հաղթողին թաքցված մանանայից կտամ՝ ուտի, և կտամ նրան սպիտակ ընտրաքար և դրա վրա գրված մի նոր անուն, որ ոչ ոք չգիտի, բացի այն ստացողից\"»։","18":"«Թիատիրայի եկեղեցու հրեշտակին գրի՛ր. \"Այսպես է ասում Աստծու Որդին, որն ունի կրակի բոցի պես աչքեր և շիկացած պղնձի նման ոտքեր.","19":"\"Գիտեմ քո գործերն ու սերը, քո հավատն ու ծառայությունը, քո համբերությունը, որ քո վերջին գործերն ավելի են, քան առաջինները։","20":"Բայց քո դեմ բան ունեմ, որովհետև թույլ ես տալիս Հեզաբելին՝ այդ կնոջը, որ իրեն \"մարգարեուհի\" է կոչում, իմ ծառաներին ուսուցանի և մոլորեցնի, որ պոռնկություն անեն և կուռքերին զոհած միս ուտեն։","21":"Ես նրան ժամանակ տվեցի, որ իր պոռնկությունից ապաշխարի, բայց նա չապաշխարեց։","22":"Ահա ես նրան անկողին կգցեմ, իսկ նրա հետ շնացողներին՝ մեծամեծ նեղությունների մեջ, եթե իրենց գործերից չապաշխարեն։","23":"Նրանց որդիներին մահվան պիտի մատնեմ, և բոլոր եկեղեցիները կիմանան, որ ես եմ հոգիներն ու սրտերը քննողը։ Եվ յուրաքանչյուրիդ ըստ ձեր գործերի կտամ։","24":"Իսկ ես ասում եմ ձեզ և մյուսներին, որ Թիատիրայում եք և այս վարդապետությանը չեք հետևում և, ինչպես ասում են, չեք ճանաչում սատանայի գաղտնի մտքերը. ձեզ վրա ուրիշ ծանրություն չեմ դնի,","25":"այլ ինչ ունեք, պահե՛ք, մինչև որ ես գամ։","26":"Հաղթողին ու իմ գործերը մինչև վերջ պահողին ազգերի վրա իշխանություն պիտի տամ։","27":"Եվ նա կհովվի նրանց երկաթե գավազանով և կփշրի նրանց բրուտի ամանի պես,","28":"ինչպես ես իշխանություն ստացա իմ Հորից, նրան կտամ նաև առավոտյան աստղը։","29":"Ով ականջ ունի, թող լսի, ինչ որ Հոգին ասում է եկեղեցիներին\"»։"},"3":{"1":"«Սարդիսի եկեղեցու հրեշտակին գրի՛ր. \"Այսպես է ասում նա, որ ունի Աստծու յոթ Հոգիները և յոթ աստղերը. “Գիտեմ քո գործերը, որ անուն ես հանել, թե կենդանի ես, բայց մեռած ես։","2":"Արթո՛ւն եղիր և գոտեպնդի՛ր մնացածներին, որ պիտի մեռնեն, որովհետև քո գործերն իմ Աստծու առաջ կատարյալ չգտա։","3":"Արդ հիշի՛ր, թե ինչպե՛ս խոսքն ընդունեցիր ու լսեցիր, և պահի՛ր այն ու ապաշխարի՛ր. իսկ եթե արթուն չլինես, ես ինչպես գող կգամ, և չես էլ իմանա, թե որ ժամին կգամ քեզ մոտ։","4":"Բայց Սարդիսում ևս ունես մի քանիսին, որոնք իրենց զգեստները չկեղտոտեցին և պիտի շրջեն ինձ հետ սպիտակ զգեստներով, որովհետև արժանի են։","5":"Հաղթողը այսպիսի սպիտակ զգեստներ պիտի հագնի, և նրա անունը կյանքի գրքից չեմ ջնջելու. և նրա անունը պիտի հայտնեմ իմ Հոր ու նրա հրեշտակների առաջ։","6":"Ով ականջ ունի, թող լսի, ինչ որ Հոգին ասում է եկեղեցիներին”\"»։","7":"«Փիլադելփիայի եկեղեցու հրեշտակին գրի՛ր. \"Այսպես է ասում Սուրբը՝ Ճշմարիտը, որ Դավթի բանալին ունի. նա, որ բացում է, և ոչ ոք չի փակում, նա, որ փակում է, և ոչ ոք չի բացում.","8":"“Գիտեմ քո գործերը. ահա քո առջև բացված դուռ դրեցի, և այն ոչ ոք չի կարող փակել, որովհետև թեև քիչ զորություն ունես, բայց իմ խոսքը պահեցիր և իմ անունը չուրացար։","9":"Ահա քեզ եմ տալիս սատանայի ժողովարան եղողներին, որոնք իրենց մասին ասում են, թե հրեա են, բայց չեն, այլ ստում են։ Նրանց այնպես պիտի անեմ, որ գան և երկրպագություն անեն քո ոտքերի առաջ ու իմանան, որ ես քեզ սիրեցի։","10":"Քանի որ համբերության իմ խոսքը պահեցիր, ես էլ քեզ պիտի պահեմ փորձության այն ժամին, որ գալու է այս աշխարհի վրա, որպեսզի փորձության ենթարկի երկրի երեսին բոլոր ապրողներին։","11":"Ահա շուտով ես գալիս եմ. պահի՛ր, ինչ որ ունես, որպեսզի ոչ ոք քո պսակը չվերցնի։","12":"Հաղթողին իմ Աստծու տաճարում սյուն պիտի դարձնեմ, ու նա այլևս այնտեղից դուրս չի գալու։ Նրա վրա պիտի գրեմ իմ Աստծու անունը և իմ Աստծու քաղաքի անունը՝ նոր Երուսաղեմի անունը, որ իջնելու է երկնքից՝ իմ Աստծու մոտից, և իմ նոր անունը պիտի գրեմ։","13":"Ով ականջ ունի, թող լսի, ինչ որ Հոգին ասում է եկեղեցիներին”\"»։","14":"«Լաոդիկիայի եկեղեցու հրեշտակին գրի՛ր. \"Այսպես է ասում Ամենը՝ հավատարիմ ու ճշմարիտ Վկան, Աստծու արարչագործության Սկիզբը.","15":"\"Գիտեմ քո գործերը, որ ո՛չ սառն ես, ո՛չ էլ տաք։ Երանի՜ սառը կամ տաք լինեիր։","16":"Ուրեմն քանի որ գաղջ ես և ո՛չ տաք, ո՛չ էլ սառը, քեզ իմ բերանից պիտի փսխեմ։","17":"Որովհետև ասում ես. \"Ես հարուստ եմ և ավելի հարստացա. ոչ մի բանի կարոտ չեմ\"։ Բայց չգիտես, որ դու թշվառ ու ողորմելի, աղքատ, կույր ու մերկ ես։","18":"Ես քեզ խորհուրդ եմ տալիս. գնի՛ր ինձնից կրակի մեջ թրծված ոսկի, որ հարստանաս, և սպիտակ զգեստներ, որ հագնես, որպեսզի քո մերկությունը չերևա, և չամաչես. աչքերիդ դե՛ղ դիր, որ տեսնես։","19":"Ում ես սիրում եմ, հանդիմանում եմ և խրատում։ Ուրեմն նախանձախնդի՛ր եղիր և ապաշխարի՛ր։","20":"Ահա ես դռան առաջ կանգնած եմ ու բախում եմ. եթե մեկն իմ ձայնը լսի և դուռը բացի, նրա մոտ կմտնեմ ու նրա հետ կընթրեմ, նա էլ՝ ինձ հետ։","21":"Հաղթողին թույլ կտամ նստել ինձ հետ իմ գահին, ինչպես ես հաղթեցի և իմ Հոր հետ նրա գահին նստեցի։","22":"Ով ականջ ունի, թող լսի, ինչ որ Հոգին ասում է եկեղեցիներին\"»։"},"4":{"1":"Դրանից հետո տեսա. ահա երկնքում մի բացված դուռ կար, և փողի պես ձայնը, որ նախկինում լսեցի, խոսում էր ինձ հետ՝ ասելով. «Բարձրացի՛ր այստեղ, և ես քեզ պիտի ցույց տամ, թե սրանից հետո ի՛նչ է լինելու»։","2":"Եվ ես իսկույն Հոգով լցվեցի։ Ահա երկնքում մի գահ էր դրված, և գահի վրա՝ մեկը նստած։","3":"Նստողը հասպիս ու սարդիոն քարերի տեսք ուներ։","4":"Գահի շուրջը կային քսանչորս աթոռներ, իսկ դրանց վրա նստած էին քսանչորս երեցներ՝ սպիտակ հանդերձներ հագած և ոսկե պսակներ գլխներին դրած։","5":"Գահից ելնում էին փայլատակումներ, որոտներ ու ձայներ. գահի առջևում կրակով բորբոքված յոթ ջահեր կային, որոնք Աստծու յոթ Հոգիներն են։","6":"Եվ գահի առաջ բյուրեղանման ապակե ծով կար։ Իսկ գահի մեջտեղում և շուրջը՝ չորս կենդանիներ՝ առջևից ու հետևից աչքերով լի։","7":"Առաջին կենդանին նման էր առյուծի, երկրորդ կենդանին՝ ցլի, երրորդ կենդանին մարդու դեմք ուներ, իսկ չորրորդ կենդանին թռչող արծվի նման էր։","8":"Չորս կենդանիներից յուրաքանչյուրը շուրջանակի վեց թև ուներ, ու ներսից լի էին աչքերով. և չէին դադարում գիշերուզօր ասելով. «Սո՛ւրբ, Սո՛ւրբ, Սո՛ւրբ, Ամենակա՛լ Տեր Աստված, որ էր և որ է և որ գալու է»։","9":"Երբ այդ կենդանիները փառք, պատիվ և գոհություն են տալիս գահի վրա նստողին, որ կենդանի է հավիտյանս հավիտենից,","10":"քսանչորս երեցներն ընկնում են աթոռի վրա նստողի առաջ, երկրպագում նրան, որ հավիտյանս հավիտենից կենդանի է, և իրենց պսակները դնում են գահի առաջ՝ ասելով.","11":"«Արժանի ես, Տե՛ր և Աստվա՛ծ մեր, որ ընդունես փառքը, պատիվը և զորությունը, որովհետև դու ամեն բան ստեղծեցիր, ու քո կամքով եղան և ստեղծվեցին»։"},"5":{"1":"Գահի վրա նստողի աջ ձեռքում մի գիրք տեսա, որ ներսից ու դրսից գրված էր և յոթ կնիքով կնքված։","2":"Մի զորավոր հրեշտակի տեսա, որ բարձրաձայն աղաղակում էր. «Ո՞վ է արժանի այս գիրքը բացելու և նրա կնիքները քանդելու».","3":"ոչ ոք՝ ո՛չ երկնքում, ո՛չ երկրի վրա, ո՛չ էլ երկրի տակ, որ կարողանար այդ գիրքը բացել և ոչ էլ նրա մեջ նայել։","4":"Ես ուժգին լալիս էի, որովհետև չգտնվեց արժանի մեկը, որ գիրքը բանա և նույնիսկ նրա մեջ նայի։","5":"Սակայն երեցներից մեկն ինձ ասաց. «Լաց մի՛ եղիր, ահա հաղթեց առյուծը՝ Հուդայի ցեղից Դավթի արմատը, որ բացելու է գիրքը և քանդելու է նրա յոթ կնիքները»։","6":"Տեսա, որ գահի, չորս կենդանիների և երեցների մեջտեղում ասես մորթված մի Գառ կար, որ յոթ եղջյուր ուներ ու յոթ աչք, որոնք Աստծու յոթ Հոգիներն են, որ ուղարկվում են ամբողջ երկրով։","7":"Նա եկավ ու վերցրեց գիրքը գահի վրա նստողի աջ ձեռքից։","8":"Երբ գիրքը վերցրեց, չորս կենդանիներն ու քսանչորս երեցներն ընկան Գառան առաջ. և յուրաքանչյուրն ուներ քնար ու խնկով լի ոսկե բուրվառ, որ սրբերի աղոթքներն են։","9":"Եվ նոր երգ էին երգում ու ասում. «Արժանի ես այդ գիրքը վերցնելու և դրա կնիքները բացելու, որովհետև մորթվեցիր ու քո արյունով մեզ գնեցիր Աստծու համար բոլոր ցեղերից ու լեզուներից, ժողովուրդներից ու ազգերից։","10":"Եվ նրանց մեր Աստծու համար թագավորներ ու քահանաներ դարձրիր, և կթագավորեն երկրի վրա»։","11":"Տեսա ու նաև լսեցի բազում հրեշտակների ձայնը գահի, չորս կենդանիների և երեցների շուրջը. նրանց թիվը բյուր-բյուրավոր և հազար-հազարավոր էր։","12":"Նրանք բարձրաձայն ասում էին. «Մորթված Գառն արժանի է ընդունելու զորություն, հարստություն, իմաստություն, ուժ, պատիվ, փառք և օրհնություն»։","13":"Լսեցի նաև, որ երկնքում, երկրի վրա, երկրի տակ և ծովում եղած բոլոր արարածները, դրանց մեջ եղած ամեն բան ասում էին. «Գահի վրա նստողին ու Գառանը լինի օրհնություն, փառք ու իշխանություն հավիտյանս հավիտենից»։","14":"Եվ չորս կենդանիներն ասում էին՝ ամեն։ Եվ քսանչորս երեցներն ընկան ու երկրպագություն արեցին։"},"6":{"1":"Տեսա, որ Գառն այն յոթ կնիքներից մեկը բացեց, և լսեցի, որ այն չորս կենդանիներից մեկը որոտի պես ձայնով ասում էր. «Արի՛»։","2":"Եվ ահա տեսա մի սպիտակ ձի, և նրա վրա նստողը մի աղեղ ուներ։ Նրան պսակ տրվեց, ու հաղթողը ելավ հաղթանակներ տանելու։","3":"Երբ երկրորդ կնիքը բացեց, երկրորդ կենդանուց լսեցի, որ ասում էր. «Արի՛»։","4":"Եվ մի ուրիշ՝ կարմիր ձի դուրս ելավ. նրա վրա նստողին արտոնվեց վերացնել խաղաղությունը երկրից, որպեսզի միմյանց սպանեն. նրան մի մեծ սուր տրվեց։","5":"Երբ երրորդ կնիքը բացեց, երրորդ կենդանուց լսեցի, որ ասում էր. «Արի՛»։ Եվ ահա տեսա մի սև ձի, և նրա վրա նստողն իր ձեռքին կշեռք ուներ։","6":"Եվ չորս կենդանիների միջից մի ձայն լսեցի, որ ասում էր. «Մի կապիճ ցորեն՝ մեկ դինարի, և երեք կապիճ գարի՝ մեկ դինարի. ձեթին ու գինուն վնաս չտաս»։","7":"Երբ չորրորդ կնիքը բացեց, չորրորդ կենդանու ձայնը լսեցի, որ ասում էր. «Արի՛»։","8":"Եվ ահա տեսա մի դեղնականաչ ձի, որի հեծյալի անունը Մահ էր, իսկ նրա հետևից գնում էր Դժոխքը։ Նրանց իշխանություն տրվեց աշխարհի մեկ քառորդի վրա սրով, սովով, մահով ու երկրի գազաններով կոտորած անելու։","9":"Երբ հինգերորդ կնիքը բացեց, զոհասեղանի տակ տեսա նրանց հոգիները, որոնք մորթվել էին Աստծու խոսքի և վկայության համար, որ պահել էին։","10":"Նրանք բարձրաձայն աղաղակում էին և ասում. «Մինչև ե՞րբ, ո՛վ սուրբ և ճշմարիտ Տեր, չպիտի դատես ու չպիտի առնես մեր արյան վրեժը երկրի վրա բնակվողներից»։","11":"Եվ նրանցից յուրաքանչյուրին սպիտակ հանդերձներ տրվեցին, ու նրանց ասվեց, որ դեռևս մի փոքր ժամանակ հանգստանան, մինչև որ լրանա նրանց ծառայակիցների ու եղբայրների թիվը, որոնք նրանց պես սպանվելու են։","12":"Տեսա՝ երբ վեցերորդ կնիքը բացեց, մեծ երկրաշարժ եղավ. արեգակը մազեղեն քրձի պես սև դարձավ, իսկ լուսինը ամբողջովին արյան պես դարձավ։","13":"Եվ երկնքի աստղերը երկրի վրա թափվեցին, ինչպես թզենին է իր խակ պտուղները թափում սաստիկ քամուց շարժվելուց։","14":"Երկինքը գալարվող մագաղաթի փաթույթի պես քաշվեց, և բոլոր լեռներն ու կղզիներն իրենց տեղից շարժվեցին։","15":"Եվ երկրի թագավորները, մեծամեծներն ու հարուստները, հազարապետներն ու զորավորները, բոլոր ծառաներն ու բոլոր ազատները թաքնվեցին քարայրներում ու լեռների ծերպերում։","16":"Եվ լեռներին ու ժայռերին ասում էին. «Ընկե՛ք մեզ վրա ու ծածկե՛ք մեզ գահի վրա նստողի երեսից և Գառան բարկությունից,","17":"որովհետև նրա բարկության մեծ օրը եկել է, և ո՞վ կարող է դիմանալ»։"},"7":{"1":"Դրանից հետո տեսա չորս հրեշտակների, որոնք կանգնել էին երկրի չորս անկյուններում և երկրի չորս քամին բռնած, որպեսզի երկրի վրա քամի չփչի, ո՛չ էլ ծովի վրա, ո՛չ էլ մի ծառի վրա։","2":"Տեսա նաև մեկ այլ հրեշտակի, որ բարձրանում էր արևելքից ու կենդանի Աստծու կնիքն ուներ։ Նա բարձրաձայն աղաղակեց այն չորս հրեշտակներին, որոնց երկրին ու ծովին վնասելու իշխանություն էր տրվել։","3":"Եվ ասում էր. «Վնաս մի՛ տվեք երկրին, ո՛չ ծովին և ո՛չ էլ ծառերին, մինչև որ մեր Աստծու ծառաների ճակատներին կնիք դնենք»։","4":"Եվ կնքվածների թիվը լսեցի՝ հարյուր քառասունչորս հազար՝ կնքված Իսրայելի որդիների բոլոր ցեղերից։","5":"Հուդայի ցեղից՝ տասներկու հազար կնքված, Ռուբենի ցեղից՝ տասներկու հազար, Գադի ցեղից՝ տասներկու հազար,","6":"Ասերի ցեղից՝ տասներկու հազար, Նեփթաղիմի ցեղից՝ տասներկու հազար, Մանասեի ցեղից՝ տասներկու հազար,","7":"Շմավոնի ցեղից՝ տասներկու հազար, Ղևիի ցեղից՝ տասներկու հազար, Իսաքարի ցեղից՝ տասներկու հազար,","8":"Զաբուղոնի ցեղից՝ տասներկու հազար, Հովսեփի ցեղից՝ տասներկու հազար, Բենիամինի ցեղից՝ տասներկու հազար։","9":"Սրանից հետո տեսա. ահա մեծ ամբոխ, որին ոչ ոք չէր կարող հաշվել, կազմված բոլոր ազգերից, ցեղերից, ժողովուրդներից ու լեզուներից, որոնք կանգնած էին աթոռի և Գառան առաջ՝ սպիտակ զգեստներ հագած և արմավենու ճյուղեր իրենց ձեռքերին։","10":"Եվ բարձրաձայն աղաղակում էին ու ասում. «Փրկությունը մեր Աստծունն է, որ նստում է աթոռի վրա, և Գառանը»։","11":"Եվ բոլոր հրեշտակները կանգնել էին աթոռի, երեցների և չորս կենդանիների շուրջը և երեսի վրա ընկնում էին աթոռի առաջ ու երկրպագում էին Աստծուն՝","12":"ասելով. «Ամե՛ն. օրհնությունը, փառքը, իմաստությունը, գոհությունը, պատիվը, ուժը և զորությունը մեր Աստծուն լինեն հավիտյանս հավիտենից։ Ամեն»։","13":"Եվ երեցներից մեկն ինձ հարցրեց. «Սրանք, որ սպիտակ զգեստներ են հագել, ովքե՞ր են և որտեղի՞ց են եկել»։","14":"Ես նրան ասացի. «Տե՛ր, դու գիտես»։ Եվ նա ինձ ասաց. «Սրանք են, որ մեծ նեղությունից են գալիս և իրենց զգեստները լվացին ու Գառան արյունով սպիտակեցրին։","15":"Դրա համար Աստծու գահի առաջն են և նրա տաճարում գիշերուզօր նրան են պաշտում, և գահի վրա նստողը հովանի պիտի լինի նրանց վրա։","16":"Այլևս ո՛չ քաղցելու են, ո՛չ էլ ծարավելու, և ո՛չ արևը նրանց վրա կընկնի, ո՛չ էլ տապը,","17":"որովհետև Գառը, որ գահի մեջտեղում է, կհովվի նրանց ու կառաջնորդի դեպի կենաց ջրի աղբյուրները, և Աստված կսրբի ամեն արտասուք նրանց աչքերից»։"},"8":{"1":"Երբ յոթերորդ կնիքը բացեց, երկնքում մոտ կես ժամ լռություն եղավ։","2":"Եվ տեսա յոթ հրեշտակներին, որ կանգնած էին Աստծու առաջ, և որոնց յոթ փող տրվեց։","3":"Մի ուրիշ հրեշտակ եկավ և կանգնեց զոհասեղանի առաջ. նա ոսկե խնկաման ուներ, և նրան շատ խունկ տրվեց, որպեսզի բոլոր սրբերին աղոթք մատուցի ոսկե զոհասեղանի վրա, որ գահի առաջ էր։","4":"Եվ խնկի ծուխը սրբերի աղոթքի հետ հրեշտակի ձեռքից Աստծու առաջ բարձրացավ։","5":"Հրեշտակը խնկամանը վերցրեց ու զոհասեղանի կրակով լցրեց և երկրի վրա գցեց. եղան ձայներ, որոտումներ, փայլատակումներ ու երկրաշարժ։","6":"Եվ յոթ հրեշտակները, որ յոթ փողեր ունեին, պատրաստվեցին հնչեցնելու։","7":"Առաջին հրեշտակը փողը հնչեցրեց, և եղավ կարկուտ ու արյան հետ խառնված կրակ ու թափվեց երկրի վրա, և այրվեց երկրի մեկ երրորդ մասը, և ծառերի մեկ երրորդ մասը, ու ամբողջ դալար խոտը։","8":"Երկրորդ հրեշտակը փողը հնչեցրեց, և վառվող մեծ լեռան նման մի բան ծովի մեջ ընկավ, ու ծովի մեկ երրորդ մասն արյուն դարձավ։","9":"Եվ ծովային կենդանիների մեկ երրորդ մասը մեռավ, ու նավերի մեկ երրորդ մասը ոչնչացավ։","10":"Երրորդ հրեշտակը փողը հնչեցրեց, և երկնքից ջահի պես վառվող մի մեծ աստղ ընկավ գետերի մեկ երրորդ մասի և ջրերի աղբյուրների վրա։","11":"Այդ աստղի անունը Օշինդր էր։ Ջրերի մեկ երրորդը դառնացավ, ու շատ մարդիկ մեռան դառնացած ջրերից։","12":"Չորրորդ հրեշտակը փողը հնչեցրեց, և խոցվեց արեգակի մեկ երրորդը, և լուսնի մեկ երրորդը, և աստղերի մեկ երրորդը, որպեսզի նրանց մեկ երրորդ մասը խավարի, ու ցերեկը լույսի մեկ երրորդը չտվեց, և գիշերը՝ նմանապես։","13":"Տեսա և լսեցի մի արծվի, որ թռչում էր երկնքի մեջ ու բարձրաձայն ասում. «Վա՛յ, վա՛յ, վա՛յ երկրի վրա բնակվողներին, երբ կհնչեն նաև մյուս փողերի ձայները, որ հնչեցնելու են երեք հրեշտակները»։"},"9":{"1":"Հինգերորդ հրեշտակը փողը հնչեցրեց, և տեսա՝ երկնքից մի աստղ ընկավ երկրի վրա. և նրան անդունդի գբի բանալին տրվեց։","2":"Անդունդի գուբը բացեց, ու գբից մեծ հնոցի ծխի պես ծուխ ելավ, և արեգակն ու օդը գբի ծխից խավարեցին։","3":"Ծխից երկրի վրա մորեխներ դուրս ելան։ Նրանց տրվեց իշխանություն, ինչպիսին որ երկրի կարիճներն ունեն։","4":"Եվ նրանց արգելվեց վնաս տալ երկրի խոտին ու ծառին, այլ միայն այն մարդկանց, որոնք իրենց ճակատներին Աստծու կնիքը չունեն։","5":"Եվ նրանց իշխանություն տրվեց, որ նրանց չսպանեն, այլ հինգ ամիս չարչարեն։ Եվ նրանց չարչարանքը նման էր այն չարչարանքին, երբ կարիճը խայթում է մարդուն։","6":"Եվ այն օրերին մարդիկ մահ պիտի փնտրեն ու այն չպիտի գտնեն, պիտի ցանկանան մեռնել, բայց մահը նրանցից պիտի փախչի։","7":"Եվ մորեխները նման էին պատերազմի պատրաստ ձիերի։ Նրանց գլուխներին կարծես ոսկե պսակներ էին, իսկ երեսները նման էին մարդկանց երեսների։","8":"Եվ կանանց մազերի պես մազեր ունեին, իսկ նրանց ատամներն առյուծի ատամների նման էին։","9":"Ունեին զրահներ՝ նման երկաթե զրահների։ Եվ նրանց թևերի ձայնը նման էր պատերազմի արշավող բազում ձիակառքերի ձայնի։","10":"Եվ ունեին պոչեր, ինչպես կարիճները, ու նրանց պոչերին խայթոցներ կային։ Եվ նրանց իշխանություն էր տրված մարդկանց հինգ ամիս չարչարելու։","11":"Եվ իրենց վրա թագավոր ունեին անդունդի հրեշտակին։ Նրա անունը եբրայերեն Աբադդոն էր, իսկ հունարեն՝ Ապոլլիոն։","12":"Մեկ վայն անցավ. ահա տակավին սրանից հետո գալիս են երկու վայը։","13":"Վեցերորդ հրեշտակը փողը հնչեցրեց, և մի ձայն լսեցի Աստծու առաջ գտնվող ոսկե զոհասեղանի չորս եղջյուրներից,","14":"որ ասում էր փող ունեցող վեցերորդ հրեշտակին. «Արձակի՛ր այն չորս հրեշտակներին, որ կապված են Եփրատ մեծ գետի վրա»։","15":"Եվ արձակվեցին չորս հրեշտակները, որոնք պատրաստված էին ժամվա, օրվա, ամսվա և տարվա համար, որպեսզի սպանեն մարդկանց մեկ երրորդին։","16":"Եվ նրանց ձիավոր զորքի թիվը երկու բյուրերի բյուր էր, և լսեցի նրանց թիվը։","17":"Եվ այսպես տեսիլքում տեսա ձիերին։ Նրանց վրա նստողները հրեղեն, հակինթե ու ծծմբե զրահներ ունեին։ Ձիերի գլուխները առյուծի գլուխների նման էին։ Նրանց բերանից կրակ, ծուխ և ծծումբ էր ելնում։","18":"Մարդկանց մեկ երրորդ մասը մեռավ այս երեքի հարվածներից՝ կրակից, ծխից ու ծծմբից, որ ելնում էին նրանց բերանից,","19":"որովհետև ձիերի զորությունը իրենց բերանում է և իրենց պոչերի մեջ. նրանց պոչերը նման էին օձերի, որ ունեին գլուխներ և դրանցով վնասում էին։","20":"Իսկ մնացած մարդիկ, որ այս հարվածներից չմեռան, չապաշխարեցին իրենց ձեռքերի գործերից, որպեսզի դևերին, ոսկե, արծաթե, պղնձե, քարե ու փայտե կուռքերին չերկրպագեն, որոնք ո՛չ տեսնել կարող են, ո՛չ լսել և ո՛չ էլ քայլել։","21":"Եվ չապաշխարեցին իրենց մարդասպանություններից, ո՛չ էլ իրենց կախարդանքներից, ո՛չ էլ իրենց պոռնկությունից, ո՛չ էլ իրենց գողություններից։"},"10":{"1":"Տեսա մի ուրիշ զորավոր հրեշտակի՝ երկնքից իջնելիս, ամպով պարուրված ու գլխին ծիածան։ Նրա երեսն արեգակի նման էր, ոտքերը՝ հրե սյուների։","2":"Նա իր ձեռքին մի բացված գրքույկ ուներ։ Աջ ոտքը ծովի վրա դրեց, ձախը՝ ցամաքի։","3":"Եվ բարձրաձայն աղաղակեց, ինչպես առյուծն է մռնչում։ Երբ աղաղակեց, յոթ որոտներն իրենց ձայնով խոսեցին։","4":"Երբ յոթ որոտներն իրենց ձայնով խոսեցին, պիտի գրեի, սակայն երկնքից մի ձայն լսեցի, որն ասում էր. «Կնքի՛ր այն, ինչ յոթ որոտները խոսեցին, և սրանք մի՛ գրիր»։","5":"Եվ այն հրեշտակը, որին տեսա ցամաքի և ծովի վրա կանգնած, իր աջ ձեռքը դեպի երկինք բարձրացրեց","6":"և երդվեց նրանով, որ հավիտյանս հավիտենից Կենդանի է, որն ստեղծեց երկինքը ու այն, ինչ նրանում է, և երկիրը ու այն, ինչ նրանում է, և ծովը ու այն, ինչ նրանում է, որ այլևս ժամանակ չի լինելու։","7":"Իսկ այն օրերին, երբ յոթերորդ հրեշտակը փողը հնչեցնի, պիտի կատարվի Աստծու խորհուրդը, ինչպես իր ծառա մարգարեներին ավետեց։","8":"Եվ ձայնը, որ երկնքից լսեցի, ինձ հետ դարձյալ խոսեց ու ասաց. «Գնա վերցրո՛ւ այն բացված գիրքը, որ ծովի ու ցամաքի վրա կանգնած հրեշտակի ձեռքին է»։","9":"Ես հրեշտակի մոտ գնացի ու նրան ասացի. «Տո՛ւր ինձ այդ գրքույկը»։ Եվ նա ինձ ասաց. «Վերցրո՛ւ և կե՛ր դա, և որովայնիդ մեջ այն կդառնանա, իսկ բերանիդ մեջ մեղրի պես քաղցր կլինի»։","10":"Եվ գրքույկը հրեշտակի ձեռքից վերցրի ու կերա։ Եվ բերանիս մեջ մեղրի պես քաղցր էր. երբ կերա, որովայնիս մեջ դառնացավ։","11":"Եվ ինձ ասաց. «Դու պետք է դարձյալ մարգարեանաս ժողովուրդների, ազգերի, լեզուների և շատ թագավորների մասին»։"},"11":{"1":"Եվ ինձ գավազանի նման մի եղեգ տրվեց՝ ասելով. «Վե՛ր կաց և չափի՛ր Աստծու տաճարը, զոհասեղանն ու նրա մեջ գտնվող երկրպագողներին։","2":"Իսկ գավիթը, որ տաճարից դուրս է, դո՛ւրս թող ու մի՛ չափիր, որովհետև այն հեթանոսներին է տրվել, որոնք սուրբ քաղաքը քառասուներկու ամիս ոտքի կոխան պիտի դարձնեն։","3":"Իմ երկու վկաներին իշխանություն կտամ, և հազար երկու հարյուր վաթսուն օր քուրձ հագած կմարգարեանան։","4":"Սրանք են այն երկու ձիթենիները և երկու ճրագակալները, որոնք երկրի Տիրոջ առաջ կանգնած են։","5":"Եթե մեկը կամենա նրանց վնասել, նրանց բերանից կրակ կելնի ու նրանց թշնամիներին կլափի։ Եվ եթե մեկը կամենա նրանց վնասել, այսպես պիտի սպանվի։","6":"Նրանք իշխանություն ունեն երկինքը փակելու, որպեսի նրանց մարգարեանալու օրերին անձրև չգա, և իշխանություն ունեն ջրերի վրա՝ դրանք արյան վերածելու և երկիրը բոլոր պատուհասներով հարվածելու, քանի անգամ որ կամենան։","7":"Եվ երբ իրենց վկայությունը ավարտած կլինեն, նրանց հետ կպատերազմի անդունդից ելնող գազանը, կհաղթի նրանց և կսպանի նրանց։","8":"Եվ նրանց դիակներն ընկած կմնան այն մեծ քաղաքի հրապարակում, որ այլաբանորեն Սոդոմ և Եգիպտոս է կոչվում, որտեղ էլ խաչվեց նրանց Տերը։","9":"Եվ ժողովուրդներից ու ցեղերից, լեզուներից ու ազգերից երեքուկես օր կտեսնեն նրանց դիակները և թույլ չեն տա, որ նրանց գերեզման դնեն։","10":"Եվ երկրի վրա բնակվողները կուրախանան ու նրանց վրա կցնծան, միմյանց ընծաներ կուղարկեն, որովհետև այս երկու մարգարեները երկրի վրա բնակվողներին չարչարեցին»։","11":"Եվ երեքուկես օր հետո Աստծուց կենաց հոգի մտավ նրանց մեջ, և նրանք ոտքի ելան, ու նրանց տեսնողների վրա մեծ ահ ընկավ։","12":"Եվ երկնքից ուժեղ ձայն լսեցին, որ նրանց ասում էր. «Այստե՛ղ բարձրացեք»։ Եվ ամպով երկինք բարձրացան, ու նրանց թշնամիները նայում էին նրանց։","13":"Այդ ժամին մեծ երկրաշարժ եղավ, ու քաղաքի մեկ տասներորդ մասը կործանվեց։ Եվ երկրաշարժից յոթ հազար մարդ մեռավ, իսկ մնացածները մեծ ահով բռնվեցին ու երկնքի Աստծուն փառք տվեցին։","14":"Երկրորդ վայն անցավ, և շուտով երրորդ վայն է գալու։","15":"Յոթերորդ հրեշտակը փողը հնչեցրեց, ու երկնքում ուժեղ ձայներ եղան, որ ասում էին. «Աշխարհի թագավորությունը մեր Տիրոջն ու նրա Օծյալինը դարձավ, և նա պիտի թագավորի հավիտյանս հավիտենից»։","16":"Եվ քսանչորս երեցները, որ Աստծու առաջ նստած էին իրենց աթոռներին, ընկան իրենց երեսների վրա և երկրպագեցին Աստծուն՝ ասելով.","17":"«Գոհություն ենք հայտնում քեզ, Տե՛ր Աստված Ամենակալ, որ էիր և ես, որ քո մեծ զորությունն առար ու թագավորեցիր։","18":"Ազգերը զայրացան, և վրա հասավ քո բարկությունը, ու ժամանակը՝ մեռելներին դատելու և վարձատրելու քո ծառաներին՝ մարգարեներին, սրբերին ու քո անունից վախեցողներին, փոքրերին ու մեծերին, և կործանելու երկիրն ապականողներին»։","19":"Եվ բացվեց Աստծու տաճարը երկնքում, և երևաց Ուխտի տապանակը իր տաճարում։ Եվ եղան փայլատակումներ, ձայներ ու որոտումներ, երկրաշարժ ու ուժեղ կարկուտ։"},"12":{"1":"Եվ երկնքում մի մեծ նշան երևաց. մի կին՝ արևով պարուրված, լուսինն էլ իր ոտքերի տակ և իր գլխին տասներկու աստղերով պսակ։","2":"Նա, հղի լինելով, աղաղակում էր երկունքի ցավերից և տառապանքից, որ ծներ։","3":"Եվ երկնքում մի ուրիշ նշան երևաց. ահա մի մեծ հրաշեկ վիշապ, որ յոթ գլուխ ուներ և տասը եղջյուր, և նրա գլուխների վրա՝ յոթ թագ։","4":"Եվ նրա պոչը քաշում էր երկնքի աստղերի մեկ երրորդ մասը և երկրի վրա գցում։ Վիշապը կանգնած էր այն կնոջ առաջ, որ պատրաստվում էր ծննդաբերել, որպեսզի երբ ծներ, նրա զավակին կուլ տար։","5":"Եվ նա մի արու զավակ ծնեց, որ բոլոր ազգերին երկաթե գավազանով պիտի հովվի. նրա որդին հափշտակվեց Աստծու և նրա գահի մոտ։","6":"Եվ կինն անապատ փախավ, որտեղ Աստծուց պատրաստված տեղ ուներ, որպեսզի այնտեղ նրան կերակրեն հազար երկու հարյուր վաթսուն օր։","7":"Եվ երկնքում պատերազմ եղավ. Միքայելն ու իր հրեշտակները վիշապի դեմ պատերազմեցին։ Վիշապն ու իր հրեշտակները ևս պատերազմեցին,","8":"բայց չկարողացան դիմադրել, ոչ էլ նրանց համար երկնքում տեղ գտնվեց։","9":"Եվ ցած գցվեց մեծ վիշապը՝ առաջին օձը, որ դև և սատանա է կոչվում. ամբողջ աշխարհը մոլորեցնողը երկրի վրա ընկավ, և նրա հրեշտակներն էլ նրա հետ ընկան։","10":"Եվ երկնքից ուժեղ ձայն լսեցի, որ ասում էր. «Այժմ եղավ մեր Աստծու փրկությունը, զորությունն ու թագավորությունը, իշխանությունը նրա Օծյալի, որովհետև ընկավ մեր եղբայրների դեմ չարախոսը, որ գիշերուզօր մեր Աստծու առաջ չարախոսում էր նրանց մասին։","11":"Եվ նրանք հաղթեցին նրան Գառան արյունով ու իրենց վկայության խոսքով և իրենց կյանքը չսիրեցին մինչև մահ։","12":"Դրա համար ուրախացե՛ք, ո՛վ երկինք և նրանում բնակվողներ։ Վա՜յ երկրին ու ծովին, որովհետև ձեզ մոտ իջավ դևը, որ մեծ բարկություն ունի՝ իմանալով, որ քիչ ժամանակ ունի»։","13":"Երբ վիշապը տեսավ, որ երկիր ընկավ, հետապնդեց այն կնոջը, որ արու զավակ ծնեց։","14":"Եվ կնոջը արծվի երկու մեծ թևեր տրվեցին, որպեսզի անապատ թռչի՝ իր տեղը, որտեղ կերակրվում է որոշ ժամանակ, մի ժամանակաշրջան ու կես ժամանակաշրջան՝ օձից հեռու։","15":"Եվ օձն իր բերանից գետի պես ջուր թափեց կնոջ հետևից, որպեսզի նրան ընկղմի։","16":"Բայց երկիրը կնոջն օգնեց. երկիրը բացեց իր բերանը և կուլ տվեց այն գետը, որ վիշապը թափել էր իր բերանից։","17":"Վիշապը բարկացավ կնոջ վրա ու գնաց նրա մյուս զավակների դեմ պատերազմելու, որոնք պահում են Աստծու պատվիրանները և ունեն Հիսուսի վկայությունը։","18":"Եվ նա կանգնեց ծովի ավազի վրա։"},"13":{"1":"Տեսա՝ ծովից ելնում էր մի գազան, որ յոթ գլուխ ուներ և տասը եղջյուր, նրա եղջյուրների վրա կար տասը թագ, իսկ նրա գլուխների վրա՝ հայհոյության անուն։","2":"Այն գազանը, որին տեսա, հովազի նման էր. նրա ոտքերը արջի ոտքերի նման էին, իսկ բերանը՝ առյուծի բերանի։ Վիշապը նրան տվեց իր զորությունը, իր գահն ու մեծ իշխանություն։","3":"Նրա գլուխներից մեկը մահացու խոցված էր, բայց այդ մահացու վերքը առողջացավ, և ամբողջ երկիրը զարմացավ ու հետևեց գազանին։","4":"Եվ երկրպագեցին վիշապին, որ իշխանություն տվեց գազանին, և երկրպագեցին՝ գազանին ասելով. «Ո՞վ է նման այս գազանին, կամ ո՞վ կարող է նրա դեմ պատերազմել»։","5":"Նրան բերան տրվեց մեծ-մեծ խոսելու ու հայհոյելու, և նրան իշխանություն տրվեց քառասուներկու ամիս գործելու։","6":"Նա իր բերանը հայհոյանքով բացեց Աստծու դեմ՝ հայհոյելու նրա անունը, նրա բնակարանը ու երկնքում բնակվողներին։","7":"Եվ նրան իշխանություն տրվեց սրբերի դեմ պատերազմելու ու նրանց հաղթելու։ Նրան իշխանություն տրվեց բոլոր ցեղերի, ժողովուրդների, լեզուների և ազգերի վրա։","8":"Նրան երկրպագելու են երկրի վրա բնակվող բոլոր նրանք, որոնց անունները աշխարհի սկզբից ի վեր գրված չեն մորթված Գառան կյանքի գրքում։","9":"Ով ականջ ունի, թող լսի.","10":"Եթե մեկը գերեվարի, գերության պիտի քշվի, եթե մեկը սրով սպանի, սրով պիտի սպանվի։ Այստեղ է սրբերի համբերությունն ու հավատը։","11":"Տեսա մի ուրիշ գազանի, որ ելնում էր երկրից. նա գառան նման երկու եղջյուր ուներ, բայց վիշապի պես էր խոսում։","12":"Նա առաջին գազանի ամբողջ իշխանությունը գործադրում էր նրա առջև ու երկիրն ու նրա բնակիչներին երկրպագել էր տալիս առաջին գազանին, որի մահացու վերքն առողջացել էր։","13":"Եվ մեծ նշաններ էր գործում. երկնքից կրակ էր իջեցնում երկրի վրա՝ մարդկանց առաջ։","14":"Մոլորեցնում էր երկրի վրա բնակվողներին այն նշաններով, որ նրան էին տրվել գործելու գազանի առաջ՝ ասելով երկրի բնակիչներին, որ պատրաստեն ա՛յն գազանի պատկերը, որ սրի վերք ուներ և ապրեց։","15":"Նրան իշխանություն տրվեց գազանի պատկերին շունչ տալու, որպեսզի պատկերը խոսի և գործի, իսկ ովքեր գազանի պատկերին չերկրպագեն, սպանվեն։","16":"Եվ բոլորի՝ փոքրերի ու մեծամեծների, հարուստների ու աղքատների, ազատների ու ծառաների աջ ձեռքին կամ նրանց ճակատին դրոշմ էր դնում,","17":"որպեսզի ոչ ոք չկարողանա գնել կամ վաճառել, բացի նրանից, ով գազանի անվան դրոշմը կամ նրա անվան համարն ունի։","18":"Այստեղ է իմաստությունը։ Ով միտք ունի, թող հաշվի գազանի թիվը, որ մարդու թիվ է, և նրա թիվը վեց հարյուր վաթսունվեց է։"},"14":{"1":"Տեսա՝ ահա Գառը կանգնած էր Սիոն սարի վրա, նրա հետ էլ՝ հարյուր քառասունչորս հազար հոգի, որոնք իրենց ճակատներին ունեին գրված նրա անունը և նրա Հոր անունը։","2":"Եվ երկնքից ձայն լսեցի՝ նման ջրերի ուժեղ ձայնի և հուժկու որոտի ձայնի, լսեցի նաև ձայն՝ նման քնարահարների, երբ իրենց քնարներն էին նվագում։","3":"Եվ մի նոր երգ էին երգում գահի առաջ, չորս կենդանիների առաջ ու երեցների առաջ, և ոչ ոք այդ երգը չէր կարող սովորել, բացի հարյուր քառասունչորս հազարից, որոնք երկրից գնվեցին։","4":"Սրանք են, որ կանանց հետ չխառնակվեցին, որովհետև կույս են. սրանք գնում են Գառի հետևից, ուր էլ նա գնա։ Սրանք գնվեցին մարդկանցից՝ Աստծուն և Գառին իբրև երախայրի։","5":"Եվ նրանց բերանում սուտ խոսք չգտնվեց, որովհետև անարատ են։","6":"Տեսա երկնքում թռչող մի ուրիշ հրեշտակի, որ հավիտենական ավետիս ուներ ավետարանելու երկրի վրա բնակվողներին, բոլոր ազգերին ու ցեղերին, բոլոր լեզուներին ու ժողովուրդներին։","7":"Նա բարձրաձայն ասում էր. «Վախեցե՛ք Աստծուց ու փա՛ռք տվեք նրան, որովհետև նրա դատաստանի ժամը եկել է, և երկրպագե՛ք երկինքն ու երկիրը, ծովն ու ջրերի աղբյուրներն Ստեղծողին»։","8":"Նրան հետևեց մեկ այլ՝ երկրորդ հրեշտակ՝ ասելով. «Ընկա՜վ, ընկա՜վ մեծն Բաբելոնը, որն իր պոռնկության թունդ գինուց խմեցրեց բոլոր ազգերին»։","9":"Եվ նրանց հետևեց մեկ այլ՝ երրորդ հրեշտակ՝ բարձրաձայն ասելով. «Ով երկրպագում է գազանին ու նրա պատկերին և դրոշմ է ընդունում իր ճակատին կամ ձեռքին,","10":"նա Աստծու ցասման գինուց պիտի խմի, որ անխառն լցված է նրա բարկության բաժակի մեջ, և պիտի տանջվի սուրբ հրեշտակների ու Գառան առաջ կրակի և ծծմբի մեջ։","11":"Եվ նրանց տանջանքի ծուխը բարձրանում է հավիտյանս հավիտենից. գիշեր-ցերեկ հանգիստ չունեն նրանք, ովքեր երկրպագում են գազանին ու նրա պատկերին և ընդունում են նրա անվան դրոշմը»։","12":"Այստեղ է սրբերի համբերությունը, որոնք պահողներն են Աստծու պատվիրանների ու Հիսուսի հավատի։","13":"Եվ երկնքից մի ձայն լսեցի, որ ասում էր. «Գրի՛ր. \"Երանի այն մեռելներին, որոնք այսուհետև Տիրոջով են ննջում։ Այո՛, Հոգին ասում է, որ իրենց տքնությունից կհանգստանան, քանի որ նրանց գործերը հետևում են նրանց\"»։","14":"Տեսա՝ ահա մի սպիտակ ամպ, և ամպի վրա նստել էր Մարդու Որդուն նման մեկը, որ գլխին ոսկե պսակ և ձեռքին սուր գերանդի ուներ։","15":"Եվ տաճարից ելավ մի ուրիշ հրեշտակ, որ բարձրաձայն աղաղակում էր ամպի վրա նստածին. «Քո գերանդին ուղարկի՛ր ու հնձի՛ր, որովհետև հնձելու ժամանակը եկել է, քանի որ երկրի հունձը հասել է»։","16":"Ամպի վրա նստածն իր գերանդին երկրի վրա դրեց, ու երկիրը հնձվեց։","17":"Մի ուրիշ հրեշտակ դուրս ելավ երկնքում գտնվող տաճարից. սա ևս սուր գերանդի ուներ։","18":"Զոհասեղանից մեկ այլ հրեշտակ դուրս ելավ, որ կրակի վրա իշխանություն ուներ, և սուր գերանդի ունեցողին բարձրաձայն գոչեց՝ ասելով. «Քո սուր գերանդին ուղարկի՛ր ու երկրի այգու ողկույզները քաղի՛ր, որովհետև նրա խաղողը հասել է»։","19":"Եվ հրեշտակն իր գերանդին երկրի վրա դրեց, երկրի այգու խաղողը քաղեց և դրեց Աստծու բարկության մեծ հնձանի մեջ։","20":"Եվ հնձանը քաղաքից դուրս կոխոտվեց, և արյունը հնձանից հոսեց, մինչև ձիերի սանձերը՝ մոտ հազար վեց հարյուր ասպարեզ։"},"15":{"1":"Երկնքում մի ուրիշ մեծ ու զարմանալի նշան տեսա. յոթ հրեշտակների, որոնք ունեին վերջին յոթ պատուհասները, որովհետև Աստծու բարկությունը նրանցով կատարվեց։","2":"Տեսա նաև ապակե ծով՝ կրակի հետ խառնված, և նրանց, ովքեր հաղթեցին գազանին, նրա պատկերին ու նրա անվան թվին, որ կանգնած էին ապակե ծովի վրա և Աստծու քնարներն ունեին։","3":"Եվ երգում էին Աստծու ծառա Մովսեսի երգն ու Գառան երգը՝ ասելով. «Մեծ ու զարմանալի են քո գործերը, Տե՛ր Աստված Ամենակալ (Սաղ. 86.10), արդար ու ճշմարիտ են քո ճանապարհները, ո՛վ ազգերի Թագավոր։","4":"Ո՞վ է, որ չի երկնչելու, Տե՛ր (Երմ. 10.7), և քո անունը չի փառավորելու, որովհետև միայն դու ես սուրբ, որովհետև բոլոր ազգերը պիտի գան ու քո առաջ պիտի երկրպագություն անեն (Սաղ. 86.9), քանի որ քո դատաստանները հայտնի դարձան»։","5":"Դրանից հետո տեսա, որ երկնքում բացվեց տաճարի վկայության խորանը։","6":"Տաճարից ելնում էին յոթ հրեշտակները, որոնք ունեին յոթ պատուհասները։ Նրանք մաքուր և փայլուն կտավ էին հագել և կրծքին ոսկե գոտիներ կապել։","7":"Այն չորս կենդանիներից մեկը յոթ հրեշտակներին յոթ ոսկե գավաթներ տվեց՝ հավիտյանս հավիտենից կենդանի Աստծու բարկությամբ լի։","8":"Եվ տաճարը լցվեց Աստծու փառքի ու նրա զորության ծխով։ Եվ ոչ ոք չէր կարող տաճար մտնել, մինչև յոթ հրեշտակների յոթ պատուհասները չկատարվեին։"},"16":{"1":"Եվ տաճարից բարձր ձայն լսեցի, որ ասում էր յոթ հրեշտակներին. «Գնացե՛ք և Աստծու բարկության գավաթները երկրի վրա՛ թափեք»։","2":"Առաջինը գնաց և իր գավաթը երկրի վրա թափեց։ Չար ու ցավոտ պալարներ գոյացան այն մարդկանց վրա, որոնք գազանի դրոշմն ունեին և նրա պատկերին էին երկրպագում։","3":"Երկրորդն իր գավաթը ծովը թափեց, և ջրերը մեռելի արյան վերածվեցին։ Ամեն կենդանի արարած, որ ծովում էր, սատկեց։","4":"Երրորդն իր գավաթը գետերի ու ջրերի աղբյուրների մեջ թափեց, և արյան վերածվեցին։","5":"Եվ ջրերի հրեշտակից լսեցի, որ ասում էր. «Արդար ես, որ ես և էիր, Սո՛ւրբդ, որ այս դատաստաններն արեցիր։","6":"Քանի որ սրբերի ու մարգարեների արյունը թափեցին, դրա համար էլ նրանց արյուն տվեցիր խմելու, որին արժանի են»։","7":"Զոհասեղանից ձայն լսեցի, որ ասում էր. «Այո՛, Տե՛ր Աստված Ամենակալ, ճշմարիտ ու արդար են քո դատաստանները»։","8":"Չորրորդը իր գավաթն արևի վրա թափեց։ Եվ նրան իշխանություն տրվեց, որ կրակով խորշակահար անի մարդկանց։","9":"Եվ մարդիկ սաստիկ տապից խորշակահար եղան ու Աստծու անվանը հայհոյեցին, որ այս պատուհասների վրա իշխանություն ունի, սակայն չապաշխարեցին, որպեսզի նրան փառք տան։","10":"Հինգերորդն իր գավաթը գազանի գահի վրա թափեց, և նրա թագավորությունը խավար դարձավ, և ցավից կծում էին իրենց լեզուները։","11":"Եվ երկնքի Աստծուն իրենց ցավերի ու պալարների պատճառով հայհոյում էին և իրենց գործերի համար չէին ապաշխարում։","12":"Վեցերորդն իր գավաթը թափեց մեծ գետի՝ Եփրատի վրա, և նրա ջուրը ցամաքեց, որպեսզի Արևելքի թագավորների ճանապարհը պատրաստվի։","13":"Եվ տեսա՝ վիշապի, գազանի և սուտ մարգարեի բերանից երեք պիղծ ոգիներ էին ելնում՝ նման գորտերի։","14":"Քանի որ նրանք դևերի ոգիներ են, նշաններ գործելիս գնում են ամբողջ աշխարհի թագավորների մոտ, որպեսզի նրանց պատերազմի հավաքեն Ամենակալ Աստծու այն մեծ օրվա համար։","15":"«Ահա գալիս եմ, ինչպես գողը. երանի՜ նրան, ով արթուն է և պահում է իր զգեստները, որ մերկ ման չգա, ու նրա ամոթանքը չտեսնեն»։","16":"Եվ նրանց հավաքեցին այնտեղ, որ եբրայերեն Արմագեդոն է կոչվում։","17":"Յոթերորդն իր գավաթն օդի մեջ թափեց, և տաճարից ու գահից բարձր ձայն ելավ, որ ասում էր. «Եղա՛վ»։","18":"Եվ եղան ձայներ, փայլատակումներ և որոտներ, ու մեծ երկրաշարժ եղավ, որպիսին չէր եղել երկրի վրա մարդու ստեղծվելուց ի վեր։","19":"Եվ մեծ քաղաքը երեք մասի բաժանվեց, և ազգերի քաղաքներն ընկան։ Մեծ Բաբելոնը հիշվեց Աստծու առաջ, որպեսզի իր ցասման թունդ գինու բաժակը նրան տա։","20":"Եվ բոլոր կղզիները փախան, և լեռներ չգտնվեցին։","21":"Եվ երկնքից մարդկանց վրա խոշոր՝ մեկ տաղանդաչափ կարկուտ էր թափվում։ Եվ մարդիկ հայհոյեցին Աստծուն այդ կարկտի հարվածի համար, որովհետև նրա պատուհասը սաստիկ մեծ էր։"},"17":{"1":"Եկավ յոթ գավաթներ ունեցող յոթ հրեշտակներից մեկը ու խոսեց ինձ հետ՝ ասելով. «Արի՛, քեզ պիտի ցույց տամ այն մեծ պոռնիկի դատաստանը, որ շատ ջրերի վրա է նստում։","2":"Նրա հետ պոռնկացան երկրի թագավորները, իսկ երկրի բնակիչները նրա պոռնկության գինուց հարբեցին»։","3":"Եվ ինձ հոգով առաջնորդեց մի անապատ, ու տեսա կարմիր գազանի վրա նստած մի կնոջ, որ լի էր հայհոյության անուններով և ուներ յոթ գլուխ ու տասը եղջյուր։","4":"Կինը հագել էր ծիրանի ու կարմիր զգեստ և զարդարվել էր ոսկով, թանկագին քարերով ու մարգարիտներով։ Նա ձեռքին մի ոսկե բաժակ ուներ՝ լի գարշանքով և պոռնկության պղծությամբ։","5":"Եվ նրա ճակատին խորհրդավոր մի անուն էր գրված՝ «Մեծ Բաբելոն՝ մայրը պոռնիկների և երկրի գարշելիների»։","6":"Տեսա այդ կնոջը՝ սրբերի ու Հիսուսի վկաների արյունով արբած։ Երբ նրան տեսա, մեծապես զարմացա։","7":"Հրեշտակն ինձ ասաց. «Ինչո՞ւ զարմացար։ Ես քեզ կասեմ խորհուրդը այդ կնոջ և նրան իր վրա կրող գազանի, որ յոթ գլուխ ունի և տասը եղջյուր։","8":"Գազանը, որին տեսար, որ կար և այժմ չկա, ելնելու է անդունդից և դեպի կորուստ է գնալու։ Եվ պիտի զարմանան երկրի վրայի այն բնակիչները, որոնց անուններն աշխարհի սկզբից ի վեր գրված չեն կյանքի գրքում, երբ տեսնեն այդ գազանին, որ կար և այժմ չկա, բայց վերստին գալու է։","9":"Այստեղ իմաստուն միտք պետք է ունենալ. յոթ գլուխները յոթ լեռներն են, որոնց վրա կինը նստել է, ինչպես նաև յոթ թագավորներն են.","10":"նրանցից հինգն ընկան, և մեկը թագավորում է, իսկ մյուսը դեռ չի եկել, և երբ գա, քիչ ժամանակ պետք է մնա։","11":"Եվ այն գազանը, որ կար ու չկա, ութերորդ թագավորն է, բայց այն յոթից է և դեպի կորստյան է գնալու։","12":"Եվ այն տասը եղջյուրները, որ տեսար, տասը թագավորներ են, որոնք դեռ թագավորություն չեն ստացել, այլ այն գազանի հետ որպես թագավոր մեկ ժամ իշխանություն պիտի ստանան։","13":"Սրանք միակարծիք են. իրենց զորությունն ու իշխանությունը տալիս են գազանին։","14":"Սրանք պատերազմելու են Գառան հետ, և Գառը հաղթելու է նրանց, որովհետև տերերի Տերն է ու թագավորների Թագավորը։ Եվ ովքեր նրա հետ են, կանչվածներ են, ընտրյալներ ու հավատարիմներ»։","15":"Եվ ինձ ասաց. «Ջրերը, որ տեսար, որտեղ պոռնիկը նստած է, դրանք ժողովուրդներն են, բազմությունները, ազգերն ու լեզուները։","16":"Տասը եղջյուրները, որ տեսար, և գազանը, նրանք պիտի ատեն պոռնիկին, պիտի նրան ամայացնեն, մերկացնեն, նրա մարմինը պիտի ուտեն և կրակով այրեն նրան,","17":"քանի որ Աստված նրանց սրտերի մեջ դրեց, որ իր կամքը կատարեն, միակարծիք լինեն և իրենց թագավորությունը գազանին տան, մինչև որ Աստծու խոսքերը կատարվեն։","18":"Եվ կինը, որին տեսար, այն մեծ քաղաքն է, որ թագավորում է երկրի թագավորների վրա»։"},"18":{"1":"Դրանից հետո տեսա երկնքից իջնող մի ուրիշ հրեշտակի, որ մեծ իշխանություն ուներ։ Եվ երկիրը նրա փառքից լուսավորվեց։","2":"Նա բարձրաձայն, ուժգին աղաղակեց ու ասաց. «Ընկա՜վ, ընկա՜վ մեծ Բաբելոնը ու դարձավ դևերի բնակավայր, արգելանոց բոլոր պիղծ հոգիների և վանդակ բոլոր անմաքուր ու ատելի թռչունների։","3":"Որովհետև նրա պոռնկության թունդ գինուց խմեցին բոլոր ազգերը, և երկրի թագավորները նրա հետ պոռնկացան, ու երկրի վաճառականները նրա զեխության զորությունից հարստացան»։","4":"Երկնքից մի ուրիշ ձայն լսեցի, որ ասում էր. «Դո՛ւրս ելեք դրա միջից, իմ ժողովո՛ւրդ, որպեսզի դրա մեղքերին մասնակից չլինեք ու դրա պատուհասները չընդունեք,","5":"որովհետև դրա մեղքերը կուտակվեցին մինչև երկինք, և Աստված դրա անիրավությունները հիշեց։","6":"Հատուցե՛ք դրան, ինչպես դա ձեզ հատուցեց, և նրան իր գործերի չափով կրկնապատի՛կը տվեք։ Այն բաժակով, որ նա լցրեց, նրան կրկնապատի՛կ լցրեք։","7":"Որքան իրեն փառավորեց ու զեխացավ, այնքան տանջանք և սո՛ւգ տվեք նրան, որովհետև նա իր սրտում ասում է. \"Թագուհի եմ նստել, այրի չեմ և բնավ սուգ չեմ տեսնի\"։","8":"Դրա համար մեկ օրում նրա վրա կգան իր պատուհասները՝ մահ, սուգ և սով, և կրակով պիտի այրվի, որովհետև զորավոր է Տերը՝ Աստված՝ նրան դատապարտողը։","9":"Եվ նրա վրա պիտի լան ու ողբան երկրի թագավորները, որոնք նրա հետ պոռնկացան և զեխություն արեցին։ Երբ նրա այրվելու ծուխը տեսնեն,","10":"նրա տանջանքի վախից հեռու կանգնած՝ կասեն. \"Վա՜յ, վա՜յ քեզ, մեծ քաղա՛ք Բաբելոն, հզո՛ր քաղաք, որ դատաստանդ մեկ ժամում հասավ\"։","11":"Եվ երկրի վաճառականները նրա վրա ողբ և սուգ պիտի անեն, որովհետև այլևս ոչ ոք չի գնելու իրենց ապրանքը՝","12":"ոսկին և արծաթը, թանկարժեք քարերը և մարգարիտը, բեհեզը և ծիրանին, մետաքսը և որդան կարմիրը, խնկե ամեն տեսակ փայտ և փղոսկրյա ամեն անոթ, ամեն ազնիվ փայտից ու պղնձից, երկաթից ու մարմարից պատրաստված անոթ,","13":"դարչին, խունկեր, յուղ, կնդրուկ, գինի, ձեթ, ալյուր, ցորեն, արջառներ, ոչխարներ, ձիեր և կառքեր, մարմիններ և մարդկային կյանքեր։","14":"Եվ հոգուդ ցանկալի պտուղները քեզանից հեռացան, ինչպես և ամեն պարարտություն և լուսափայլ վայելչություն, և դրանք այլևս չես գտնելու։","15":"Վաճառականները, որոնք դրանցով հարստացան, կկանգնեն հեռվում՝ նրա տանջանքի երկյուղից լաց ու սուգ անելով, կասեն.","16":"\"Վա՜յ, վա՜յ, մե՛ծ քաղաք, որ հագել էիր բեհեզ, ծիրանի ու որդան կարմիր և զարդարվել ոսկով, պատվական քարերով ու մարգարտով,","17":"որովհետև մեկ ժամում այդքան հարստությունն ավերակ դարձավ\"։ Նավավարների ողբը Ու ամեն նավավար և բոլոր նրանք, ովքեր ծովում են աշխատում, հեռվում կանգնեցին","18":"և նրա այրվելու ծուխը տեսնելով՝ աղաղակում էին և ասում. \"Ո՞ր քաղաքն էր այս մեծ քաղաքին նման\"։","19":"Եվ իրենց գլուխներին հող էին ցանում և լաց ու սուգ անելով՝ մեծաձայն աղաղակում ու ասում. \"Վա՜յ, վա՜յ, մե՛ծ քաղաք, որով հարստացան ծովի վրա բոլոր մեծ նավեր ունեցողները, որովհետև մեկ ժամում ավերակ դարձավ\"։","20":"Ուրախացե՛ք նրա վրա, երկի՛նք, սո՛ւրբ առաքյալներ և մարգարեներ, որովհետև Աստված ձեր դատաստանն արեց դրա դեմ»։","21":"Եվ մի հզոր հրեշտակ երկանաքարի պես մի մեծ քար վերցրեց ու ծովի մեջ գցեց՝ ասելով. «Այսպիսի հարձակումով պիտի ընկնի Բաբելոն մեծ քաղաքը ու այլևս գոյություն չպիտի ունենա։","22":"Եվ քնարահարների ու երաժիշտների, սրնգահարների ու փողահարների ձայնն այլևս քո մեջ չպիտի լսվի, և քո մեջ այլևս ոչ մի արհեստավոր չպիտի գտնվի, ու երկանքի ձայն այլևս չպիտի լսվի քո մեջ։","23":"Ճրագի լույսն այլևս չպիտի փայլի քո մեջ. փեսայի և հարսի ձայնն այլևս քո մեջ բնավ չպիտի լսվի, որովհետև քո վաճառականները երկրի մեծամեծներն էին։ Որովհետև քո կախարդությամբ մոլորվեցին բոլոր ազգերը։","24":"Եվ քո մեջ գտնվեց արյունը մարգարեների, սրբերի և երկրի վրա մորթված բոլոր մարդկանց»։"},"19":{"1":"Դրանից հետո երկնքում լսեցի մեծ բազմության բարձր ձայն, որ ասում էր. «Ալելո՛ւիա, փրկությո՜ւն, փա՜ռք ու զորությո՜ւն մեր Աստծուն,","2":"որովհետև նրա դատաստանները ճշմարիտ ու արդար են, որովհետև նա դատեց մեծ պոռնիկին, որ ապականեց երկիրը իր պոռնկության մեջ և իր ծառաների արյան վրեժը նրանից լուծեց (Բ Օր. 32.43, Դ Թագ. 9.7)»։","3":"Եվ երկրորդ անգամ ասացին. «Ալելո՛ւիա»։ Եվ նրա ծուխը բարձրանում էր հավիտյանս հավիտենից։","4":"Եվ ընկան քսանչորս երեցներն ու չորս կենդանիները և երկրպագեցին Աստծուն, որ նստած էր գահին, ու ասացին. «Ամե՛ն, ալելո՛ւիա»։","5":"Եվ գահից մի ձայն ելավ՝ ասելով. «Օրհնեցե՛ք մեր Աստծուն, նրա բոլոր ծառանե՛ր ու նրանից երկյուղողնե՛ր, փոքրե՛ր ու մեծե՛ր»։","6":"Եվ լսեցի մի ձայն՝ նման մեծ բազմության և առատ ջրերի, ինչպես ձայնը ուժեղ որոտի, որ ասում էր. «Ալելո՛ւիա, որովհետև թագավորեց Ամենակալ Տերը՝ Աստված։","7":"Ուրախանանք և ցնծանք ու փառք տանք նրան, որովհետև Գառան հարսանիքը հասավ, և նրա կինը պատրաստեց ինքն իրեն։","8":"Նրան տրվեց, որ հագնի սպիտակ, մաքուր և լուսափայլ բեհեզ», որովհետև բեհեզը սրբերի արդարությունն է։","9":"Եվ ինձ ասաց. «Գրի՛ր. \"Երանելի են Գառան հարսանիքի ընթրիքին կանչվածները\"»։ Եվ ինձ ասաց. «Սրանք Աստծու ճշմարիտ խոսքերն են»։","10":"Ես նրա ոտքերի առաջ ընկա, որպեսզի երկրպագեմ նրան, իսկ նա ինձ ասաց. «Զգո՛ւյշ եղիր, մի՛ արա, ես ծառայակից եմ քեզ ու քո եղբայրներին, որոնք Հիսուս Քրիստոսի վկայությունն ունեն։ Տեր Աստծո՛ւն երկրպագիր, որովհետև Հիսուսի վկայությունը մարգարեության հոգին է»։","11":"Եվ տեսա երկինքը բացված, և ահա մի սպիտակ ձի, որի վրա նստողը կոչվում էր «Հավատարիմ» ու «Ճշմարիտ»։ Նա արդարությամբ է դատում ու պատերազմում։","12":"Նրա աչքերը կրակի բոցի պես էին, ու նրա գլխի վրա բազում պսակներ կային։ Նա ուներ գրված մի անուն, որ ոչ ոք չգիտեր, բացի իրենից։","13":"Հագել էր արյունով ներկված զգեստ. նրա անունն էր «Բան Աստծու»։","14":"Եվ երկնային զորությունները, սպիտակ և մաքուր բեհեզ հագած, սպիտակ ձիերի վրա գնում էին նրա հետևից։","15":"Նրա բերանից սրած սուր էր ելնում, որպեսզի նրանով ազգերին հարվածի. և նրանց հովվում է երկաթե գավազանով։ Նա է տրորում Ամենակալ Աստծու ահեղ բարկության գինու հնձանը։","16":"Նրա զգեստի և ազդրի վրա գրված էր անունը՝ «ԹԱԳԱՎՈՐՆԵՐԻ ԹԱԳԱՎՈՐ ՈՒ ՏԵՐԵՐԻ ՏԵՐ»։","17":"Տեսա մի ուրիշ հրեշտակի, որ կանգնած էր արեգակի վրա։ Նա բարձրաձայն աղաղակեց՝ ասելով երկնքում թռչող բոլոր թռչուններին. «Եկե՛ք, հավաքվե՛ք Աստծու մեծ ընթրիքին,","18":"որպեսզի ուտեք մարմինները թագավորների, հազարապետների, հզորների, ձիերի ու նրանց վրա նստողների, և բոլորի մարմինները՝ ազատների և ծառաների, մեծերի և փոքրերի»։","19":"Տեսա գազանին, երկրի թագավորներին ու նրանց զորքերին հավաքված՝ պատերազմելու ձիու վրա նստողի և նրա զորքերի դեմ։","20":"Եվ բռնվեց գազանը, նրա հետ նաև սուտ մարգարեն, որ նրա առաջ նշաններ էր գործում, որոնցով մոլորեցնում էր նրանց, ովքեր գազանի դրոշմն ընդունեցին, և նրանց, ովքեր նրա պատկերին երկրպագեցին։ Նրանց երկուսին էլ ողջ-ողջ ծծմբով այրվող կրակի լճի մեջ գցեցին։","21":"Իսկ մնացածները սպանվեցին ձիու վրա նստողի սրով, որ նրա բերանից էր ելնում։ Եվ բոլոր թռչունները նրանց մարմիններից կշտացան։"},"20":{"1":"Տեսա երկնքից իջնող մի հրեշտակի, որ անդունդի բանալին ուներ և մի մեծ շղթա իր ձեռքին։","2":"Նա բռնեց վիշապին՝ այն առաջին օձին, որ դևն է և սատանան, և հազար տարով կապեց նրան։","3":"Նրան գցեց անդունդը, փակեց ու վրան կնիք դրեց, որ այլևս ազգերին չմոլորեցնի, մինչև հազար տարին լրանա. դրանից հետո նա փոքր ժամանակով պետք է արձակվի։","4":"Տեսա աթոռներ, որոնց վրա նստողներին դատելու իշխանություն տրվեց, տեսա նաև այն հոգիներին, որոնք գլխատվել էին Հիսուսի վկայության ու Աստծու խոսքի համար, և նրանց, որոնք չերկրպագեցին գազանին ու ոչ էլ նրա պատկերին և չընդունեցին նրա դրոշմը իրենց ճակատին, ոչ էլ իրենց ձեռքին։ Նրանք կենդանացան ու Քրիստոսի հետ հազար տարի թագավորեցին։","5":"Իսկ մնացած մեռելները չկենդանացան, մինչև հազար տարին լրանա։ Սա է առաջին հարությունը։","6":"Երանելի և սուրբ է նա, ով բաժին ունի առաջին հարության մեջ. նրանց վրա երկրորդ մահն իշխանություն չունի։ Նրանք Աստծու և Քրիստոսի քահանաները պիտի լինեն և նրա հետ հազար տարի պիտի թագավորեն։","7":"Երբ հազար տարին լրանա, սատանան իր բանտից պիտի արձակվի","8":"և պիտի դուրս գա, որ մոլորեցնի երկրի չորս անկյուններում գտնվող ազգերին, Գոգին ու Մագոգին։ Նա նրանց պատերազմի պիտի հավաքի, որոնց թիվը ծովի ավազի չափ է։","9":"Եվ պիտի բարձրանան երկրի լայնությամբ և պիտի շրջապատեն սրբերի բանակն ու սիրելի քաղաքը։ Բայց երկնքից կրակ իջավ ու լափեց նրանց,","10":"իսկ դևը՝ նրանց մոլորեցնողը, կրակի ու ծծմբի լիճը գցվեց, որտեղ էին գազանը և սուտ մարգարեն։ Եվ գիշերուզօր պիտի չարչարվեն հավիտյանս հավիտենից։","11":"Տեսա մի սպիտակ մեծ գահ ու նրա վրա նստողին, որի երեսից երկինքն ու երկիրը փախան, և նրանց համար տեղ չգտնվեց։","12":"Եվ գահի առաջ կանգնած մեծ ու փոքր մեռելներ տեսա։ Գրքեր բացվեցին, և մի ուրիշ գիրք էլ բացվեց, որ է կենաց գիրքը։ Եվ մեռելները դատվեցին ըստ այդ գրքերում գրվածի՝ իրենց գործերի համաձայն։","13":"Եվ ծովն իր մեջ եղած մեռելներին տվեց, մահն ու դժոխքը՝ իրենց միջի մեռելներին, և յուրաքանչյուրը համաձայն իր գործերի դատվեց։","14":"Մահն ու դժոխքը հրե լիճը գցվեցին. սա է երկրորդ մահը։","15":"Եվ ով կենաց գրքի մեջ գրված չգտնվեց, նա հրե լիճը գցվեց։"},"21":{"1":"Տեսա նոր երկինք ու նոր երկիր, որովհետև առաջին երկինքն ու երկիրն անցան, և այլևս ծով չկա։","2":"Տեսա սուրբ քաղաքը՝ նոր Երուսաղեմը, որ իջնում էր երկնքից՝ Աստծու մոտից, պատրաստված և ինչպես իր ամուսնու համար զարդարված մի հարս։","3":"Եվ գահից մի ուժեղ ձայն լսեցի, որ ասում էր. «Ահա Աստծու խորանը, որ նա բնակվելու է մարդկանց հետ։ Նրանք կլինեն նրա ժողովուրդները, իսկ ինքը կլինի նրանց Աստվածը, որ նրանց հետ է։","4":"Եվ նրանց աչքերից պիտի սրբի ամեն արտասուք. այլևս մահ չի լինելու, չի լինելու նաև ո՛չ սուգ, ո՛չ աղաղակ, ո՛չ ցավ, որովհետև նախկիններն անցան»։","5":"Եվ գահի վրա նստողն ասաց. «Ահա ամեն բան նոր եմ դարձնում»։ Եվ ասաց. «Գրի՛ր, որ այս խոսքերը ճշմարիտ ու հավաստի են»։","6":"Եվ ինձ ասաց. «Եղա՛վ. ես եմ Ալֆան և Օմեգան, Սկիզբն ու Վերջը։ Ես եմ ծարավածին ձրի տալու կենաց ջրի աղբյուրից։","7":"Հաղթողն է դա ժառանգելու. ես նրա Աստվածն եմ լինելու, իսկ նա իմ որդին է լինելու։","8":"Իսկ վախկոտների, անհավատների, պիղծերի, մարդասպանների, պոռնիկների, կախարդների, կռապաշտների ու բոլոր ստախոսների բաժինը կրակով և ծծմբով այրվող այս լճում է, որ երկրորդ մահն է»։","9":"Եվ եկավ մեկն այն յոթ հրեշտակներից, որոնք վերջին յոթ պատուհասներով լի յոթ գավաթներն ունեին։ Նա խոսեց ինձ հետ ու ասաց. «Արի՛, քեզ պիտի ցույց տամ հարսին՝ Գառան կնոջը»։","10":"Եվ ինձ Հոգով տարավ մի մեծ ու բարձր լեռ և ցույց տվեց ինձ սուրբ քաղաքը՝ Երուսաղեմը, որ իջնում էր երկնքից՝ Աստծու մոտից։","11":"Նա Աստծու փառքն ուներ, և նրա լուսավորությունը թանկարժեք քարի էր նման, ինչպես բյուրեղյա հասպիսը։","12":"Նա ուներ մեծ ու բարձր պարիսպ, տասներկու դռներ և դռների վրա՝ տասներկու հրեշտակներ և նրանց գրված անունները, որոնք Իսրայելի տասներկու ցեղերի անուններն են։","13":"Արևելյան կողմից՝ երեք դուռ, հյուսիսայինից՝ երեք դուռ, հարավայինից՝ երեք դուռ և արևմտյանից՝ երեք դուռ։","14":"Քաղաքի պարիսպը տասներկու հիմքեր ուներ, դրանց վրա՝ Գառան տասներկու առաքյալների անունները։","15":"Ինձ հետ խոսողը մի ոսկե եղեգյա երիզաչափ ուներ, որպեսզի չափեր քաղաքը, նրա դռներն ու պարիսպները։","16":"Քաղաքը քառակուսի էր. նրա երկարությունը հավասար էր լայնությանը։ Եվ չափեց քաղաքը եղեգով՝ տասներկու հազար ասպարեզ. նրա երկարությունը, լայնությունը և բարձրությունը հավասար էին։","17":"Չափեց նրա պարիսպը՝ հարյուր քառասունչորս կանգուն, մարդու չափով, որ գործածում էր հրեշտակը։","18":"Եվ նրա պարսպի շինվածքը հասպիսից էր։ Քաղաքը մաքուր ոսկի էր, մաքուր ապակու նման։","19":"Քաղաքի պարսպի հիմքերը զարդարված էին ամեն տեսակ թանկարժեք քարերով. առաջին հիմքը՝ հասպիս, երկրորդը՝ շափյուղա, երրորդը՝ ագաթ, չորրորդը՝ զմրուխտ,","20":"հինգերորդը՝ եղնգնաքար, վեցերորդը՝ սարդիոն, յոթերորդը՝ ոսկեքար, ութերորդը՝ բյուրեղ, իններորդը՝ տպազիոն, տասներորդը՝ ոսկեկանաչ, տասնմեկերորդը՝ հակինթ, տասներկուերորդը՝ մեղեսիկ։","21":"Եվ տասներկու դռները՝ տասներկու մարգարիտներից, յուրաքանչյուր դուռը՝ մեկ մարգարիտից. քաղաքի հրապարակը՝ մաքուր ոսկի, ինչպես թափանցիկ ապակի։","22":"Եվ նրա մեջ տաճար չտեսա, որովհետև Տեր Աստված Ամենակալը և Գառն է նրա տաճարը։","23":"Քաղաքը ո՛չ արևի, ո՛չ էլ լուսնի կարիք ունի, որպեսզի իրեն լուսավորեն, որովհետև Աստծու փառքն է լուսավորում նրան, և Գառը՝ նրա ճրագը։","24":"Եվ ազգերն ընթանալու են նրա լույսով, և երկրի թագավորներն իրենց փառքը նրան են բերելու։","25":"Նրա դռները ցերեկը չեն փակվելու, որովհետև այնտեղ գիշեր չի լինելու։","26":"Եվ ազգերի փառքն ու պատիվը այնտեղ են բերվելու։","27":"Եվ նրա մեջ չի մտնելու ոչ մի անմաքրություն, ոչ էլ պղծություն և ստություն անողը, այլ միայն նրանք, ովքեր գրված են Գառան կենաց գրքում։"},"22":{"1":"Հրեշտակն ինձ ցույց տվեց կենաց ջրի գետը՝ փայլուն, ինչպես բյուրեղը, որ բխում էր Աստծու ու Գառան գահից։","2":"Եվ նրա հրապարակի մեջտեղում՝ գետի այս ու այն կողմերում, կենաց ծառն էր, որ տասներկու պտուղ էր տալիս. ամեն ամիս իր պտուղն էր տալիս, իսկ ծառի տերևները ազգերին բժշկելու համար էին։","3":"Այնտեղ այլևս նզովք չի լինելու։ Աստծու ու Գառան գահը նրա մեջ է լինելու, և նրա ծառաները պաշտելու են նրան։","4":"Եվ տեսնելու են նրա երեսը, և նրա անունը նրանց ճակատների վրա է լինելու։","5":"Այնտեղ գիշեր չի լինելու. ճրագի և արեգակի լույսի կարիք չի լինելու, որովհետև Տերը՝ Աստված է լուսավորելու նրանց, և պիտի թագավորեն հավիտյանս հավիտենից։","6":"Եվ ինձ ասաց. «Այս խոսքերը հավաստի և ճշմարիտ են։ Տերը՝ մարգարեների հոգիների Աստվածը, ուղարկեց իր հրեշտակին, որ իր ծառաներին ցույց տա այն, ինչ շուտով պիտի լինի»։","7":"«Ահա շուտով պիտի գամ. երանի՜ նրան, ով պահում է այս գրքի մարգարեության խոսքերը»։","8":"Եվ ես՝ Հովհաննեսս, այս բաները լսողն ու տեսնողը, երբ լսեցի ու տեսա, ընկա, որ երկրպագեմ այն հրեշտակի ոտքերի առաջ, որ այս բաները ցույց էր տալիս ինձ։","9":"Եվ նա ինձ ասաց. «Զգուշացի՛ր, մի՛ արա այս, որովհետև ես ծառայակից եմ քեզ, քո եղբայր մարգարեներին և այս գրքի մարգարեության խոսքերը պահողներին. Աստծո՛ւն երկրպագիր»։","10":"Եվ ինձ ասաց. «Այս գրքի մարգարեության խոսքերը կնքված մի՛ պահիր, որովհետև ժամանակը մոտ է։","11":"Անիրավություն գործողը թող ավելի անիրավանա, և կեղտոտը թող ավելի կեղտոտվի, և արդարը թող ավելի արդարանա, և սուրբը թող ավելի սրբանա։","12":"Ահա շուտով պիտի գամ, և իմ վարձը ինձ հետ է, որպեսզի յուրաքանչյուրին ըստ իր գործերի հատուցեմ։","13":"Ես եմ Ալֆան ու Օմեգան, Սկիզբն ու Վերջը, Առաջինն ու Վերջինը»։","14":"Երանելի են նրա պատվիրանները պահողները, որովհետև նրանցն է իշխանությունը կենաց ծառի վրա և քաղաքի դռնով ներս մտնելու։","15":"Դրսում շներն են, կախարդները, պոռնիկները, մարդասպանները, կռապաշտները և ստություն սիրող ու գործող բոլորը։","16":"«Ես՝ Հիսուսս, ուղարկեցի իմ հրեշտակին, որ այս բաները վկայի ձեզ՝ եկեղեցիներիդ։ Ես եմ Դավթի արմատն ու սերունդը և առավոտյան փայլող աստղը»։","17":"Հոգին ու հարսն ասում են. «Արի՛»։ Լսողը ևս ասում է. «Արի՛։ Թող գա, ով ծարավ է, և ով կամենում է, թող ձրի վերցնի կենաց ջուրը»։","18":"Ես վկայում եմ ամեն մեկին, ով լսում է այս գրքի մարգարեության խոսքերը։ Եթե մեկը սրանց վրա բան ավելացնի, Աստված նրա վրա կավելացնի այն պատուհասները, որ գրված են այս գրքում։","19":"Եվ եթե մեկն այս գրքի մարգարեության խոսքերից բան պակասեցնի, Աստված նրա բաժինը կպակասեցնի կենաց ծառից, սուրբ քաղաքից և այս գրքում գրվածներից։","20":"Այս բաները վկայողն ասում է. «Այո՛, ես շուտով պիտի գամ»։ Ամե՛ն։ Արի՛, Տե՛ր Հիսուս։","21":"Մեր Տեր Հիսուս Քրիստոսի շնորհը ձեզ բոլորիդ հետ լինի։ Ամե՛ն։"}};
